questionvariables.text:
/* Randomising vectors */

vecA:matrix([rand([1,1,-1])*(rand(2)+1)],[rand([1,1,-1])*(rand(2)+1)],[rand([1,1,-1])*(rand(2)+1)]);

vecBx:rand([1,1,-1])*(rand(3)+2);
vecBy:rand([1,1,-1])*(rand_with_prohib(2,4,[abs(vecBx)]));
vecBz:-(first(first(vecA))*vecBx + first(second(vecA))*vecBy)/first(third(vecA));

vecB:matrix([vecBx*first(third(vecA))],[vecBy*first(third(vecA))],[vecBz*first(third(vecA))]);

vecCx:determinant(matrix([first(second(vecA)),first(third(vecA))], [first(second(vecB)),first(third(vecB))]));
vecCy:determinant(matrix([first(third(vecA)),first(first(vecA))], [first(third(vecB)),first(first(vecB))]));
vecCz:determinant(matrix([first(first(vecA)),first(second(vecA))], [first(first(vecB)),first(second(vecB))]));

vecC:matrix([vecCx],[vecCy],[vecCz]);

/* Randomising the choice of face and edge */

faceHighlight:rand(3)+1;
faceHighName: if faceHighlight=1 then "CDFG" else if faceHighlight=2 then "BEGF" else "ADGE";

edgePoint:rand(3)+1;
edgePointName: if faceHighlight=1 then (if edgePoint=1 then "BF" else if edgePoint=2 then "EG" else "AD") else if faceHighlight=2 then (if edgePoint=1 then "AE" else if edgePoint=2 then "DG" else "CF") else (if edgePoint=1 then "BE" else if edgePoint=2 then "FG" else "CD");

/* Solutions */

tans1: if faceHighlight=1 then (if edgePoint=1 then vecB+vecC/2 else if edgePoint=2 then vecA+vecB+vecC/2 else vecA+vecC/2) else if faceHighlight=2 then (if edgePoint=1 then vecA+vecB/2 else if edgePoint=2 then vecA+vecB/2+vecC else vecB/2+vecC) else (if edgePoint=1 then vecA/2+vecB else if edgePoint=2 then vecA/2+vecB+vecC else vecA/2+vecC);

tans2: if faceHighlight=1 then vecA/2+vecB/2+vecC else if faceHighlight=2 then vecA/2+vecB+vecC/2 else vecA+vecB/2+vecC/2;

tans3:tans2-tans1;

feedbackvariables.text:
/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: Finds vector to midpoint of OE as instead of AE or similar (1) */
node3_error: if faceHighlight=1 then (if edgePoint=1 then (vecB+vecC)/2 else if edgePoint=2 then (vecA+vecB+vecC)/2 else (vecA+vecC)/2) else if faceHighlight=2 then (if edgePoint=1 then (vecA+vecB)/2 else if edgePoint=2 then (vecA+vecB+vecC)/2 else (vecB+vecC)/2) else (if edgePoint=1 then (vecA+vecB)/2 else if edgePoint=2 then (vecA+vecB+vecC)/2 else (vecA+vecC)/2);

/* Node 4: Finds vector AP instead of OP or similar (1) */
node4_error: if faceHighlight=1 then vecC/2 else if faceHighlight=2 then vecB/2 else vecA/2;

/* Node 5: 2/3 of vector components correct (1) */
node5_test: if length(intersection({float(first(first(ans1))), float(first(second(ans1))), float(first(third(ans1)))}, {float(first(first(tans1))), float(first(second(tans1))), float(first(third(tans1)))}))=2 then 1 else 0;

/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: Finds vector to midpoint of OG as instead of BG or similar (1) */
node3_error: (vecA+vecB+vecC)/2;

/* Node 4: Finds vector BQ instead of OQ or similar (1) */
node4_error: if faceHighlight=1 then (vecA+vecB)/2 else if faceHighlight=2 then (vecA+vecC)/2 else (vecB+vecC)/2;

/* Node 5: 2/3 of vector components correct (1) */
node5_test: if length(intersection({float(first(first(ans2))), float(first(second(ans2))), float(first(third(ans2)))}, {float(first(first(tans2))), float(first(second(tans2))), float(first(third(tans2)))}))=2 then 1 else 0;

/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: Check ecf (1) */
ecf3:ans2-ans1;

/* Node 4: Calculating QP instead of PQ */

/* Node 5: Summing vectors from (a) and (b) instead of subtracting */
node5_error:ans2+ans1;
